/**
 * Streams a single-entity CSV file directly into the database without
buffering it in memory. Use for very large files (millions of rows)
that cannot fit in a JSON request body. Memory stays bounded
regardless of file size.

The endpoint accepts either:
  * `multipart/form-data` with a single file part named `file`
    (preferred — what the generated client and browser uploads use), or
  * `text/csv` raw body (convenient for `curl --data-binary` and back-compat).

Hard limit: 1 GB per upload.

**Response is NDJSON streamed live as the server processes the
upload.** Once pre-flight validation passes (entity name, declared
Content-Length under 1 GB), the response Content-Type switches to
`application/x-ndjson` and the server writes one JSON object per
line, terminated by `\n`:

  * `{"type":"progress","rowsParsed":N,"rowsInserted":M,"bytesProcessed":B}` —
    emitted after batch flushes, throttled to ~4/sec server-side so
    multi-million-row files don't flood the wire. `bytesProcessed`
    is optional and reports how many request-body bytes the server
    has consumed so far; the client uses it (plus the file size) to
    render a server-side progress bar and a rows/sec ETA.
  * `{"type":"result","entity":"...","rowsParsed":N,"rowsInserted":M,"durationMs":D}` —
    exactly one terminal success event whose payload matches
    `StreamCsvResult`.
  * `{"type":"error","error":"..."}` — exactly one terminal failure
    event for errors that occurred mid-stream after headers were
    sent. (Pre-flight failures still surface as conventional 4xx
    JSON responses with an `error` body.)

Clients should read the response body incrementally (browser XHR
`onprogress` + `responseText`, or fetch `body.getReader()`),
split on `\n`, and parse each non-empty line as JSON. The same
approach used by the Data Ingest page's `uploadCsvStream` helper
works in any modern browser without extra dependencies.

 * @summary Stream a single-entity CSV file (bounded-memory ingest)
 */
export const IngestCsvStreamQueryParams = zod.object({
  entity: zod
    .enum([
      "suppliers",
      "categories",
      "items",
      "purchase_orders",
      "po_lines",
      "invoices",
      "payments",
      "shipments",
    ])
    .describe("Which entity the CSV rows describe."),
});

export const IngestCsvStreamHeader = zod.object({
  "x-org-id": zod
    .string()
    .optional()
    .describe(
      "Tenant ID hint. In production, requests MUST present\n`Authorization: Bearer <token>` and `x-org-id` (if supplied) must\nmatch the org bound to that token. In development, this header is\naccepted standalone.\n",
    ),
});

